[1125] = { en = "The Spirits of Southwind", tier = 4,
  t = "De geesten van Southwind",
  d = "Ten zuidwesten van ons ligt een tragische plek: de ruïnes van Southwind Village. Hier moet ons werk beginnen, $N.$B$BVolgens wat we te weten zijn gekomen, was dit dorp ooit een uitvalsbasis van de nachtelfen in Silithus. Het is al lang geleden overspoeld door de silithid-nesten die de woestenij teisteren. Ik kan me alleen maar voorstellen hoe verschrikkelijk het was toen het dorp voor het eerst werd verwoest...$B$BDe gekwelde geesten van gevallen druïden en schildwachten dwalen doelloos door de ruïnes. Verken deze plek en bevrijd waar nodig de zielen van deze ellendige wezens.",
  o = "Bevrijd de geesten van 8 Tortured Druids en 8 Tortured Sentinels in Southwind Village en keer daarna terug naar Layo Starstrike bij de begraafplaats Valor's Rest in Silithus.",
  p = "Alliance of Horde, het maakt niet uit: geen enkel wezen verdient het om als gekwelde geest op deze wereld vast te zitten. Door deze zielen te bevrijden maak je het goed, $N.",
  c = "Ik dacht al dat het enorme, kolkende nest bij de ruïnes van het dorp misschien een rol had gespeeld bij de ondergang ervan. Je werk lijkt te bewijzen dat dit klopt: doordat het nest zo dichtbij is, is het een gevaar voor al het werk dat we hier later nog willen doen.$b$bIk dank je voor je goedheid bij het bevrijden van de zielen van de gevallenen. Zulk werk is nooit makkelijk, dat weet ik. Maar als je er klaar voor bent, wil ik je nog een keer om hulp vragen...",
  g = { {"tragische", "tragic (tragisch)"}, {"uitvalsbasis", "base of operations"}, {"overspoeld", "overrun (overspoelen)"}, {"nesten", "hives, nests (nest)"}, {"woestenij", "wastes, wasteland"}, {"teisteren", "to infest, plague"}, {"gekwelde", "tortured (kwellen)"}, {"schildwachten", "sentinels (schildwacht)"}, {"dwalen", "wander (dwalen)"}, {"doelloos", "aimlessly"}, {"ellendige", "wretched (ellendig)"}, {"kolkende", "swirling (kolken)"}, {"ondergang", "demise, downfall"}, {"goedheid", "benevolence, kindness"}, {"gevallenen", "the fallen (gevallene)"} },
},

[8277] = { en = "Deadly Desert Venom", tier = 4,
  t = "Dodelijk woestijngif",
  d = "Beetix Ficklespragg tot je dienst! Mijn neef Noggle verdient zijn brood met het verzamelen van zeldzame kruiden voor de alchemisten van Cenarion Hold. Tenminste, dat deed hij vroeger. Na zijn laatste tocht kwam hij terug met een sterk gif in zijn aderen.$B$BIk heb het gif kunnen vertragen, maar om het helemaal onschadelijk te maken heb ik gifmonsters nodig van wat hem ook maar gestoken heeft.$B$BNoggle kwam uit het noorden, dus ik durf mijn hemd te verwedden dat het stonelash-scorpids of sand skitterers waren. Breng me wat angels en giftanden, dan probeer ik een tegengif voor hem te maken.",
  o = "Beetix Ficklespragg in Cenarion Hold in Silithus wil dat je 8 Stonelash Scorpid Stingers en 8 Sand Skitterer Fangs verzamelt. Keer terug naar haar als je de taak hebt voltooid.",
  p = "Ben je klaar met het verzamelen van die monsters? We kunnen Noggle elk moment kwijtraken!",
  c = "Duim maar, vriend! Laten we hopen dat we Noggle kunnen redden!",
  g = { {"Dodelijk", "deadly"}, {"woestijngif", "desert venom"}, {"tot je dienst", "at your service"}, {"verdient zijn brood", "makes a living (zijn brood verdienen)"}, {"zeldzame", "rare (zeldzaam)"}, {"kruiden", "herbs (kruid)"}, {"aderen", "veins (ader)"}, {"vertragen", "to slow down"}, {"onschadelijk", "harmless, neutralised"}, {"gifmonsters", "poison samples (gifmonster)"}, {"gestoken", "stung (steken)"}, {"verwedden", "to bet"}, {"angels", "stingers (angel)"}, {"tegengif", "antidote"}, {"Duim maar", "cross your fingers (duimen)"} },
},

[8280] = { en = "Securing the Supply Lines", tier = 4,
  t = "De aanvoerroutes beveiligen",
  d = "Cenarion Hold is een plek van het grootste strategische belang. Ik ben ervan overtuigd dat onze overwinning op de silithid zeker is zolang we het in handen hebben. Tenminste, als de aanvoer van onze voorraden op peil kan blijven.$B$BWoestijnwormen zijn een grotere bedreiging gebleken voor onze bevoorradingskaravanen dan zelfs de silithid zelf. Vanochtend nog werd een grote lading morrowgrain verwoest door een groep dredge strikers. Ik wil dat je hun aantal uitdunt, zodat onze voorraden niet in gevaar komen.",
  o = "Windcaller Proudhorn in Cenarion Hold in Silithus wil dat je 15 Dredge Strikers doodt.",
  p = "De dredge strikers zijn een serieuze bedreiging en moeten snel worden aangepakt!",
  c = "Je hebt mijn oprechte dank. Met je hulp aan Cenarion Hold heb je echte moed getoond.",
  g = { {"aanvoerroutes", "supply lines (aanvoerroute)"}, {"beveiligen", "to secure"}, {"strategische", "strategic (strategisch)"}, {"belang", "importance"}, {"overtuigd", "convinced"}, {"aanvoer", "influx, supply"}, {"op peil", "at the right level, maintained"}, {"bevoorradingskaravanen", "supply caravans (bevoorradingskaravaan)"}, {"lading", "shipment, load"}, {"uitdunt", "thin out (uitdunnen)"}, {"aangepakt", "dealt with (aanpakken)"}, {"oprechte", "sincere (oprecht)"}, {"moed", "courage"} },
},

[1126] = { en = "Hive in the Tower", tier = 4,
  t = "Het nest in de toren",
  d = "Het nest in Southwind Village moet aangepakt worden, en ik denk dat ik weet hoe we erbij kunnen komen. Volgens mijn ervaring zijn de silithid-nesten heel gevoelig voor hun omgeving. Dat verklaart hun aanvallen als ze het doodsgejammer van de geesten horen.$B$BDe silithid zijn het sterkst in de toren: die met de massa wespen eromheen. Beklim de toren en schud het nest wakker. Kom terug en vertel wat je ontdekt, maar wees voorzichtig! Als je iets vindt dat zou kunnen helpen, breng het dan naar mij.",
  o = "Beklim de toren van Southwind Village en zoek een manier om het silithid-nest in actie te brengen. Breng alles wat je daarbij aan ongewoons vindt naar Layo Starstrike bij de begraafplaats Valor's Rest in Silithus.",
  p = "Nou, heeft het gewerkt? Je bent nog heel, dat is goed nieuws. Heb je iets gevonden?",
  c = "Wat... wat is dat?$b$bHet heeft de vorm van een... doos, misschien? Er zit een flinke korst omheen. Wacht, hier is een stukje vrij... zit er een boek onder al die smurrie?$b$bIk denk dat je hier een flinke vondst hebt gedaan, $N... nou ja, dat hoop ik tenminste. Misschien is het een dagboek of een logboek uit oude tijden, bewaard gebleven in deze schaal.$b$bIk denk dat ik weet hoe we kunnen uitvinden wat dit is.",
  g = { {"nest", "hive, nest"}, {"aangepakt", "addressed, dealt with (aanpakken)"}, {"gevoelig", "sensitive"}, {"omgeving", "environment"}, {"verklaart", "explains (verklaren)"}, {"doodsgejammer", "death wails"}, {"wespen", "wasps (wesp)"}, {"Beklim", "scale, climb (beklimmen)"}, {"schud wakker", "jostle awake (wakker schudden)"}, {"korst", "crust"}, {"smurrie", "gunk"}, {"vondst", "find"}, {"bewaard gebleven", "preserved (bewaard blijven)"}, {"schaal", "shell"}, {"uitvinden", "to find out"} },
},

[6844] = { en = "Umber, Archivist", tier = 4,
  t = "Umber, de archivaris",
  d = "Er is hier nog genoeg te doen, maar ik denk dat het belangrijk is om dit voor onderzoek terug te brengen naar de Circle. Geloof me: het werk is er nog steeds als dit allemaal achter de rug is. Als er een dagboek in dit kleverige chitine zit, dan heeft de Circle eindelijk een venster op het verleden!$B$BBreng dit naar de archivaris van de Circle in Nighthaven. Hij heet Umber, en hij is briljant. Een beetje getikt, zeker, maar toch briljant! Umber heeft boeken gered die er veel slechter aan toe waren dan dit. Als het te redden is, kan hij het.",
  o = "Breng het Encrusted Silithid Object naar Umber, de archivaris van de Cenarion Circle, in het dorp Nighthaven in Moonglade.",
  p = "Wel, hallo daar! Hrmm...$b$bIk zal een beetje eerlijk tegen je zijn, vriend... je ruikt een beetje sterk. Een tikje muf, zou je kunnen zeggen. Nu wil ik je niet persoonlijk aanvallen. Ik zeg alleen... in het vervolg wil je jezelf misschien even opfrissen als je uit het veld komt. Dan maak je bij een eerste kennismaking een wat positievere indruk!$b$bEnfin... wat kan ik voor je doen?",
  c = "Wel, grote apenpadden! Wat heb je hier? Het heeft zo'n beetje de vorm van een boek, denk ik... Ik zal proberen de schaal eraf te breken.$b$bHeeft Layo je vanuit Silithus naar mij gestuurd? Ik heb alleen heel gedempte geruchten gehoord over de verschrikkingen die daar gebeuren, al zijn ze eigenlijk niet zo gedempt als je erover nadenkt. Tel daarbij op dat ik niet van insectachtige dingen houd, en je hebt het recept voor: ik blijf hier bij de boeken!",
  g = { {"archivaris", "archivist"}, {"onderzoek", "analysis, research"}, {"achter de rug", "over and done with"}, {"kleverige", "sticky (kleverig)"}, {"chitine", "chitin"}, {"venster", "window"}, {"getikt", "touched, a bit crazy"}, {"er slechter aan toe", "in worse shape (er slecht aan toe zijn)"}, {"muf", "musty, whiffy"}, {"opfrissen", "to freshen up"}, {"kennismaking", "first meeting, introduction"}, {"Enfin", "anyhow"}, {"apenpadden", "monkey toads (apenpad)"}, {"gedempte", "hushed (gedempt)"}, {"verschrikkingen", "horrors (verschrikking)"}, {"insectachtige", "bug-like (insectachtig)"} },
},

[8278] = { en = "Noggle's Last Hope", tier = 4,
  t = "Noggles laatste hoop",
  d = "Verdorie! Het tegengif werkte niet. Noggle is vast gestoken door een van de sterkere wezens in het verre zuiden.$B$BJe moet daarheen gaan en meer monsters voor me halen, $N. Het goede nieuws is dat ik er minder nodig heb, omdat hun gif sterker is. Het slechte nieuws is dat er in het zuiden meer soorten giftige wezens rondkruipen, dus je zult van meer bronnen moeten verzamelen.",
  o = "Beetix Ficklespragg in Cenarion Hold in Silithus wil dat je 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers en 3 Rock Stalker Fangs verzamelt.",
  p = "Dit is onze laatste kans om Noggle te redden! Schiet op!",
  c = "Ja! Het lijkt te werken, Noggle komt weer bij. We staan diep bij je in het krijt!",
  g = { {"hoop", "hope"}, {"Verdorie", "blast it, damn"}, {"tegengif", "antidote"}, {"gestoken", "stung (steken)"}, {"monsters", "samples (monster)"}, {"giftige", "poisonous (giftig)"}, {"rondkruipen", "crawl around"}, {"bronnen", "sources (bron)"}, {"Schiet op", "hurry (opschieten)"}, {"komt weer bij", "is coming to (bijkomen)"}, {"bij je in het krijt", "in your debt (in het krijt staan)"} },
},

[8281] = { en = "Stepping Up Security", tier = 4,
  t = "Strengere beveiliging",
  d = "Je prestaties zijn tot nu toe echt voorbeeldig, $N. Maar onze aanvoerroutes zijn nog niet helemaal veilig. Nu de dredge strikers weg zijn, zullen hun grotere neven uit het zuiden zeker naar het noorden trekken om hun plaats in te nemen.$B$BJe zult heel wat dredge crushers moeten doden om ze op afstand te houden, maar we kunnen de veiligheid van onze aanvoerroutes niet aan het toeval overlaten.",
  o = "Windcaller Proudhorn in Cenarion Hold in Silithus wil dat je 20 Dredge Crushers doodt.",
  p = "De dredge crushers zijn een serieuze bedreiging en moeten meteen worden aangepakt!",
  c = "Uitstekend! Je hebt bewezen dat je een waardevolle bondgenoot bent bij de voorbereiding op de oorlog tegen de silithid.",
  g = { {"Strengere", "stricter, stepped-up (streng)"}, {"beveiliging", "security"}, {"prestaties", "performance (prestatie)"}, {"voorbeeldig", "exemplary"}, {"aanvoerroutes", "supply lines (aanvoerroute)"}, {"neven", "cousins (neef)"}, {"op afstand te houden", "to keep at bay (op afstand houden)"}, {"toeval", "chance"}, {"waardevolle", "valuable (waardevol)"}, {"bondgenoot", "ally"}, {"voorbereiding", "preparation"} },
},

