[8282] = { en = "Noggle's Lost Satchel", tier = 4,
  t = "Noggles verloren tas",
  d = "Waar ben ik? Waar is mijn tas? *hapt naar adem* Ik ben hem vast kwijtgeraakt toen ik vluchtte voor Deathclasp, de reusachtige scorpid. In mijn haast om te ontsnappen liep ik recht een nest stonelash flayers in.$B$BIn de tas die ik bij me had, zaten allerlei zeldzame reagentia. Zonder die spullen kunnen Beetix en ik de drankjes niet maken die Cenarion Hold nodig heeft. Ik ben nog te zwak om op te staan, maar ik zorg dat het de moeite waard is als je mijn reagentia terugbrengt.$B$BIk liep Deathclasp tegen het lijf in de bergketen in het zuiden, achter het kamp van Bronzebeard.",
  o = "Haal Noggle's Satchel op uit de bergen in het zuiden van Silithus en breng de tas terug naar hem in Cenarion Hold.",
  p = "Heb je mijn tas nog steeds niet gevonden? Nou, ik mag van geluk spreken: het gif is in elk geval weg.",
  c = "Ja! Je hebt mijn tas teruggebracht. En mijn zeldzame reagentia zijn er allemaal nog! Ik sta nog lang bij je in het krijt.",
  g = { {"verloren", "lost (verliezen)"}, {"hapt naar adem", "gasps (naar adem happen)"}, {"kwijtgeraakt", "lost (kwijtraken)"}, {"vluchtte", "fled (vluchten)"}, {"reusachtige", "giant (reusachtig)"}, {"haast", "rush, hurry"}, {"ontsnappen", "to escape"}, {"reagentia", "reagents (reagens)"}, {"drankjes", "potions (drankje)"}, {"de moeite waard", "worth your while"}, {"tegen het lijf", "ran into (tegen het lijf lopen)"}, {"bergketen", "mountain range"}, {"van geluk spreken", "count oneself lucky"}, {"in het krijt", "in debt (in het krijt staan)"} },
},

[8284] = { en = "The Twilight Mystery", tier = 4,
  t = "Het raadsel van de Twilight",
  d = "Ten noordwesten van hier bloeide ooit een kamp van sekteleden van de Twilight's Hammer. Als je er nu heen zou gaan, zou je het gebied vol elementalen vinden, met alleen nog verspreide stukken hout en canvas op de plek waar het kamp stond.$B$BIk heb een paar scherven van een kleitablet van die plek gehaald, maar ik heb er te weinig om er iets nuttigs van te maken. Kijk of je de overige tabletscherven kunt vinden, zodat we meer duidelijkheid krijgen over de aanwezigheid van de Twilight's Hammer hier in Silithus.",
  o = "Geologist Larksbane in Cenarion Hold in Silithus wil dat je 8 Twilight Tablet Fragments verzamelt.",
  p = "Je vindt het verwoeste kamp ten noordwesten van hier. Kom terug als je alle scherven hebt.",
  c = "Precies zoals ik al dacht. Ik kan losse woorden in de tabletten ontcijferen, maar ze lijken zonder enige logica of betekenis te zijn. Het is bekend dat groepen van de Twilight's Hammer een code gebruiken om de betekenis van hun teksten te verbergen. We zullen naar iemand moeten gaan die meer van dit soort dingen weet.",
  g = { {"raadsel", "mystery, riddle"}, {"bloeide", "thrived (bloeien)"}, {"sekteleden", "cultists (sektelid)"}, {"elementalen", "elementals (elementaal)"}, {"verspreide", "scattered (verspreid)"}, {"canvas", "canvas"}, {"scherven", "fragments, shards (scherf)"}, {"kleitablet", "clay tablet"}, {"nuttigs", "useful (nuttig)"}, {"overige", "remaining (overig)"}, {"duidelijkheid", "clarity, light"}, {"aanwezigheid", "presence"}, {"ontcijferen", "to decipher"}, {"verbergen", "to hide"} },
},

[4901] = { en = "Guardians of the Altar", tier = 4,
  t = "De bewakers van het altaar",
  d = "Helemaal boven op de bergkam ligt volgens mij een altaar van de godin Elune. Voor zover ik kan zien, moeten we de vijf fakkels in elke grot aansteken. Dan kunnen we direct bij het altaar komen.$B$BIn de oude ruïnes van Kel'Theril heb ik een paar toverspreuken overgeschreven die in de steen waren uitgehakt. Ik denk dat ze het geheim zijn om het altaar te openen. Ik heb je hulp nodig om elke fakkel aan te steken, terwijl ik de spreuk opzeg.$B$BAls het lukt, kun je onze ontdekkingen aan Erelas melden!",
  o = "Bescherm Ranshalla terwijl ze probeert het Altar of Elune weer te activeren. Meld je ontdekkingen aan Erelas Ambersky in Rut'theran Village.",
  c = "Heb je Ranshalla ontmoet?",
  e = "Ontdek het geheim van het Altar of Elune",
  g = { {"bewakers", "guardians (bewaker)"}, {"bergkam", "ridge"}, {"altaar", "altar"}, {"godin", "goddess"}, {"fakkels", "torches (fakkel)"}, {"aansteken", "to light"}, {"toverspreuken", "incantations, spells (toverspreuk)"}, {"overgeschreven", "copied, transcribed (overschrijven)"}, {"uitgehakt", "carved (uithakken)"}, {"opzeg", "recite (opzeggen)"}, {"ontdekkingen", "findings, discoveries (ontdekking)"}, {"melden", "to report"} },
},

[5121] = { en = "High Chief Winterfall", tier = 4,
  t = "High Chief Winterfall",
  d = "We weten nog steeds weinig over waarom de furbolgs deze vreemde stof innemen. Toch denk ik dat we er het beste een eind aan kunnen maken, voordat het uit de hand loopt.$B$BDe Winterfall-furbolgs zijn normaal geen agressieve stam. Door deze verandering in hun gedrag denk ik dat ze bevelen van hun opperhoofd moeten krijgen. De schade die al gedaan is, kunnen we waarschijnlijk niet herstellen. Maar als hun leider gedood wordt, worden ze volgens mij niet erger.$B$BGa naar het oosten, naar Winterfall Village.",
  o = "Donova Snowden in Winterspring wil dat je High Chief Winterfall verslaat.",
  p = "Misschien kom je meer te weten in Winterfall Village, $N.",
  c = "Heel erg bedankt, $N. Ik hoop dat ik weer verder kan met mijn onderzoek, zonder angst om overvallen te worden. Neem dit alsjeblieft aan als beloning.",
  g = { {"stof", "substance"}, {"innemen", "to take in, ingest"}, {"uit de hand loopt", "gets out of hand (uit de hand lopen)"}, {"agressieve", "aggressive (agressief)"}, {"stam", "tribe"}, {"gedrag", "behaviour"}, {"bevelen", "orders (bevel)"}, {"opperhoofd", "chief"}, {"schade", "damage"}, {"herstellen", "to repair, undo"}, {"verslaat", "defeat (verslaan)"}, {"overvallen", "ambushed, attacked (overvallen)"} },
},

[5123] = { en = "The Final Piece", tier = 4,
  t = "Het laatste stuk",
  d = "Het logboek dat je bij het opperhoofd hebt gevonden, lijkt uitgebreid. Maar als je een paar bladzijden doorkijkt, merk je dat je de tekst niet kunt lezen. De tekens zijn zo grof en slordig gemaakt dat je niet zeker weet of iemand ze zou kunnen lezen.$B$BMaar misschien kan Donova je vertellen wat er staat...",
  o = "Breng het Crudely-written Log naar Donova Snowden in Winterspring.",
  p = "Zo, wat is dit, $N?",
  c = "Ik vraag me af wat dit allemaal betekent... Ik kan er niets uit opmaken...",
  g = { {"logboek", "log, logbook"}, {"opperhoofd", "chief"}, {"uitgebreid", "extensive"}, {"bladzijden", "pages (bladzijde)"}, {"doorkijkt", "look through (doorkijken)"}, {"tekens", "markings, signs (teken)"}, {"grof", "crude, rough"}, {"slordig", "sloppy, poorly made"}, {"Ik kan er niets uit opmaken", "I can't make anything out of it (opmaken uit)"} },
},

[5128] = { en = "Words of the High Chief", tier = 4,
  t = "De woorden van het opperhoofd",
  d = "De Winterfall zijn geen bedreiging meer voor mij. Maar als je nog steeds wilt weten wat de furbolgs ertoe dreef om dit vreemde vuurwater te maken en te drinken, dan moet je volgens mij Kelek Skykeeper opzoeken.$B$BHij hoort bij een groep die de Emerald Circle heet: druïden die zich inzetten voor hun werk in Felwood, waar ze het land genezen van de verdorvenheid.$B$BKelek heeft veel ervaring met de furbolgs in Felwood en kan je misschien meer over het logboek vertellen.$B$BNogmaals bedankt, $N.",
  o = "Breng het Crudely-written Log naar Kelek Skykeeper in het zuiden van Felwood.",
  p = "De Emerald Circle is vriendelijk tegen iedereen, $R. Wat kan ik voor je doen?",
  c = "Ja, als je me dit een tijdje laat bekijken, kan ik het misschien voor je vertalen.$b$b<Kelek bladert door de pagina's.>$b$bAls ik het helemaal heb kunnen doorlezen, laat ik het je weten.$b$bBedankt dat je dit met me deelt, $N. Er is heel weinig bekend over de Winterfall-furbolgs.",
  g = { {"opperhoofd", "chief"}, {"bedreiging", "threat"}, {"ertoe dreef", "drove them to (drijven tot)"}, {"vuurwater", "firewater"}, {"opzoeken", "to seek out, look up"}, {"zich inzetten", "commit themselves (zich inzetten voor)"}, {"genezen", "to heal"}, {"verdorvenheid", "corruption"}, {"ervaring", "experience"}, {"Nogmaals", "again, once more"}, {"bladert", "leafs, flips through (bladeren)"}, {"doorlezen", "to read through"}, {"deelt", "share (delen)"} },
},

[6604] = { en = "Enraged Wildkin", tier = 4,
  t = "Woedende wildkin",
  d = "Heb je het verlaten kamp ten zuiden van hier gezien? Het lijkt alsof de wildkin gek zijn geworden en zo ongeveer alles hebben vernield wat ze konden vinden!$B$BIk hoorde een gerucht dat een van de overlevenden van de aanval uitrust in Starfall Village, ten westen van hier. Ik ben echt benieuwd wat er gebeurd is... jij niet?",
  o = "Spreek met Jaron Stoneshaper in Starfall Village.",
  c = "Ja, wat kan ik voor je doen?",
  g = { {"Woedende", "enraged (woedend)"}, {"verlaten", "abandoned"}, {"zo ongeveer", "just about"}, {"vernield", "destroyed (vernielen)"}, {"gerucht", "rumour"}, {"overlevenden", "survivors (overlevende)"}, {"uitrust", "is resting (uitrusten)"}, {"benieuwd", "curious"} },
},

[8283] = { en = "Wanted - Deathclasp, Terror of the Sands", tier = 4,
  t = "Gezocht - Deathclasp, Terror of the Sands",
  d = "Men denkt dat de vreselijke scorpid Deathclasp zich in de zuidelijke bergketen heeft teruggetrokken, nu de silithid actiever zijn. Ze vormt een groot gevaar voor patrouilles en expedities in het zuiden. Wie meehelpt om haar te vernietigen, wordt royaal beloond. Vraag naar een beloning bij Captain Vish Kozus, boven in de wachttoren van Cenarion Hold.",
  o = "Breng Deathclasp's Pincer naar Vish Kozus, Captain of the Guard.",
  p = "Ik heb de schaar van het beest nodig als bewijs van je daad. Geen schaar, geen beloning.",
  c = "Uitstekend! Nu Deathclasp weg is, kunnen we de zuidelijke bergketen gebruiken als strategische route om de silithid-nesten te omzeilen. We waarderen je werk enorm.",
  g = { {"Gezocht", "wanted (zoeken)"}, {"vreselijke", "terrible (vreselijk)"}, {"bergketen", "mountain range"}, {"teruggetrokken", "retreated (zich terugtrekken)"}, {"patrouilles", "patrols (patrouille)"}, {"vernietigen", "to destroy"}, {"royaal", "handsomely, generously"}, {"wachttoren", "watchtower"}, {"schaar", "pincer, claw"}, {"daad", "deed"}, {"omzeilen", "to circumvent, get around"}, {"waarderen", "to appreciate"} },
},

[8285] = { en = "The Deserter", tier = 4,
  t = "De deserteur",
  d = "Er gaan geruchten dat een lid van de Twilight's Hammer, Ortell genaamd, uit zijn sekte is gedeserteerd. Men zegt dat hij zich verstopt heeft in de bergen ten zuiden van Southwind Village, waar hij als kluizenaar leeft. Misschien kun je hem overhalen om te helpen het tablet te ontcijferen.$B$BNeem het herstelde tablet mee en zoek Ortell op.",
  o = "Breng het herstelde tablet naar Hermit Ortell in Silithus.$b",
  p = "Jij! Hoe heb je me gevonden? Wie ben je? Je bent toch niet gevolgd? Spreek!",
  c = "Ik zie dat je mijn oude organisatie kent. Je hoort vast bij Cenarion Hold.  $B$BJe zoekt informatie om tegen hen te gebruiken? Kom dichterbij, misschien kunnen we elkaar helpen.",
  g = { {"deserteur", "deserter"}, {"geruchten", "rumours (gerucht)"}, {"genaamd", "called, named"}, {"sekte", "sect, cult"}, {"gedeserteerd", "deserted (deserteren)"}, {"verstopt", "hidden (zich verstoppen)"}, {"kluizenaar", "hermit"}, {"overhalen", "to persuade, enlist"}, {"ontcijferen", "to decipher"}, {"herstelde", "restored (herstellen)"}, {"gevolgd", "followed (volgen)"}, {"organisatie", "organisation"}, {"dichterbij", "closer"} },
},

[969] = { en = "Luck Be With You", tier = 4,
  t = "Moge het geluk met je zijn",
  d = "Ah, ik zie het al aan je: jij wilt een geluksamulet laten maken. Mau'ari weet het altijd!$B$BIn het zuiden vind je een kloof, en reuzen van massief ijs. Soms dragen de reuzen ze bij zich, maar je kunt de scherven ook altijd zelf in de kloof verzamelen. Deze scherven hebben een sterke weerkaatsende kracht.$B$BBreng 10 frostmaul-scherven terug, dan krijg je mijn geluksamulet.",
  o = "Verzamel 10 Frostmaul Shards voor Witch Doctor Mau'ari in Everlook.",
  p = "Breng de scherven terug, dan vertel ik je meer!",
  c = "Ahh, ja... Ik maak het amulet nu voor je. Wacht maar even!",
  g = { {"Moge", "may (mogen)"}, {"geluksamulet", "lucky charm"}, {"kloof", "canyon, gorge"}, {"reuzen", "giants (reus)"}, {"massief", "solid"}, {"scherven", "shards (scherf)"}, {"weerkaatsende", "reflective (weerkaatsen)"}, {"kracht", "power, quality"}, {"amulet", "charm, amulet"} },
},

[975] = { en = "Cache of Mau'ari", tier = 4,
  t = "De Cache of Mau'ari",
  d = "Voordat ik je dit amulet geef, kan ik beter uitleggen hoe je het gebruikt.$B$BAls je het amulet bij je draagt, zul je merken dat de wezens waartegen je vecht bepaalde voorwerpen laten vallen. Heb je het amulet niet bij je, dan vind je ze niet. Begrepen?$B$BJe herkent deze speciale voorwerpen aan hun naam: ze heten E'ko. Als je zulke voorwerpen vindt, breng ze dan gewoon naar de oude Mau'ari, en dan helpt ze je verder.$B$BWacht hier terwijl ik je amulet klaarmaak.",
  o = "Spreek zo meteen nog een keer met Witch Doctor Mau'ari om het geluksamulet te krijgen.",
  c = "Hier is het, $N. Denk eraan: je moet het bij je dragen. Waarom ga je niet terug de wildernis in om te zien wat je daar vindt?",
  g = { {"amulet", "charm, amulet"}, {"uitleggen", "to explain"}, {"merken", "to notice, find"}, {"bepaalde", "certain (bepaald)"}, {"laten vallen", "drop"}, {"Begrepen", "understood (begrijpen)"}, {"herkent", "recognise (herkennen)"}, {"klaarmaak", "prepare, fix (klaarmaken)"}, {"zo meteen", "in a moment"}, {"geluksamulet", "lucky charm"}, {"wildernis", "wilds, wilderness"} },
},

[4801] = { en = "Frostsaber E'ko", tier = 4,
  t = "Frostsaber-E'ko",
  p = "In Winterspring vecht je tegen grote katten die frostsabers heten. Deze dieren zijn ongelooflijk snel en sluw. Wil je de snelheid van de frostsaber krijgen, breng me dan de E'ko die je bij ze vindt.$B$BDenk eraan: je moet de Cache of Mau'ari in je tassen hebben als je op E'ko wilt jagen.",
  c = "Mau'ari kan de juju eruit halen voor $N... Gebruik de Cache of Mau'ari om dit over jezelf of je bondgenoten uit te spreken.",
  g = { {"ongelooflijk", "incredibly"}, {"sluw", "cunning"}, {"snelheid", "speed"}, {"Denk eraan", "remember (eraan denken)"}, {"jagen", "to hunt"}, {"eruit halen", "to draw out, derive"}, {"bondgenoten", "allies (bondgenoot)"}, {"uit te spreken", "to cast, pronounce (uitspreken)"} },
},

[4802] = { en = "Winterfall E'ko", tier = 4,
  t = "Winterfall-E'ko",
  p = "In Winterspring vecht je tegen misleide wezens die de Winterfall-furbolgs heten. Door de wensen van hun leider hebben ze ongelooflijke kracht gekregen. Wil je de kracht van de Winterfall krijgen, breng me dan de E'ko die je bij ze vindt.$B$BDenk eraan: je moet de Cache of Mau'ari in je tassen hebben als je op E'ko wilt jagen.",
  c = "Mau'ari kan de juju eruit halen voor $N... Gebruik de Cache of Mau'ari om dit over jezelf of je bondgenoten uit te spreken.",
  g = { {"misleide", "misguided (misleid)"}, {"wensen", "wishes (wens)"}, {"ongelooflijke", "incredible (ongelooflijk)"}, {"kracht", "strength, power"}, {"Denk eraan", "remember (eraan denken)"}, {"eruit halen", "to draw out, derive"}, {"bondgenoten", "allies (bondgenoot)"}, {"uit te spreken", "to cast, pronounce (uitspreken)"} },
},

[4803] = { en = "Shardtooth E'ko", tier = 4,
  t = "Shardtooth-E'ko",
  p = "In Winterspring vind je grote beren met een heel dikke huid. Deze Shardtooth-beren zijn goed beschermd door wat ze kunnen verdragen. Wil je weerstand tegen vuur krijgen, breng me dan de E'ko die je bij de Shardtooth vindt.$B$BDenk eraan: je moet de Cache of Mau'ari in je tassen hebben als je op E'ko wilt jagen.$B$B",
  c = "Mau'ari kan de juju eruit halen voor $N... Gebruik de Cache of Mau'ari om dit over jezelf of je bondgenoten uit te spreken.",
  g = { {"huid", "hide, skin"}, {"beschermd", "protected (beschermen)"}, {"verdragen", "to withstand, endure"}, {"weerstand", "resistance"}, {"Denk eraan", "remember (eraan denken)"}, {"eruit halen", "to draw out, derive"}, {"bondgenoten", "allies (bondgenoot)"}, {"uit te spreken", "to cast, pronounce (uitspreken)"} },
},

[4804] = { en = "Chillwind E'ko", tier = 4,
  t = "Chillwind-E'ko",
  p = "In Winterspring vecht je tegen grote vliegende wezens die de Chillwind heten. Deze dieren kunnen vorstmagie gebruiken. Wil je weerstand tegen vorst krijgen, breng me dan de E'ko die je bij de Chillwind vindt.$B$BDenk eraan: je moet de Cache of Mau'ari in je tassen hebben als je op E'ko wilt jagen.$b",
  c = "Mau'ari kan de juju eruit halen voor $N... Gebruik de Cache of Mau'ari om dit over jezelf of je bondgenoten uit te spreken.",
