[4805] = { en = "Ice Thistle E'ko", tier = 4,
  t = "Ice Thistle-E'ko",
  p = "In Winterspring vecht je tegen grote wezens die de ice thistle-yeti's heten. Deze dieren bewegen langzaam, maar dankzij de bescherming van hun dikke vacht kunnen ze veel klappen ontwijken. Wil je aanvallen leren ontwijken, breng me dan de E'ko die je bij ze vindt.$B$BDenk eraan: je moet de Cache of Mau'ari in je tassen hebben als je op E'ko wilt jagen.$b",
  c = "Mau'ari kan de juju eruit halen voor $N... Gebruik de Cache of Mau'ari om dit over jezelf of je bondgenoten uit te spreken.",
  g = { {"dankzij", "thanks to"}, {"bescherming", "protection"}, {"vacht", "fur"}, {"klappen", "blows (klap)"}, {"ontwijken", "to evade, dodge"}, {"Denk eraan", "remember (eraan denken)"}, {"eruit halen", "to draw out, derive"}, {"bondgenoten", "allies (bondgenoot)"}, {"uit te spreken", "to cast, pronounce (uitspreken)"} },
},

[4806] = { en = "Frostmaul E'ko", tier = 4,
  t = "Frostmaul-E'ko",
  p = "In Winterspring heb je gevochten tegen de grote ijsreuzen die frostmaul heten. Ze beschikken over pure macht en kracht. Wil je de kracht van de frostmaul krijgen, breng me dan de E'ko die je bij ze vindt.$B$BDenk eraan: je moet de Cache of Mau'ari in je tassen hebben als je op E'ko wilt jagen.",
  c = "Mau'ari kan de juju eruit halen voor $N... Gebruik de Cache of Mau'ari om dit over jezelf of je bondgenoten uit te spreken.",
  g = { {"ijsreuzen", "ice giants (ijsreus)"}, {"beschikken over", "have at their disposal"}, {"pure", "sheer, pure (puur)"}, {"macht", "power"}, {"Denk eraan", "remember (eraan denken)"}, {"eruit halen", "to draw out, derive"}, {"bondgenoten", "allies (bondgenoot)"}, {"uit te spreken", "to cast, pronounce (uitspreken)"} },
},

[4807] = { en = "Wildkin E'ko", tier = 4,
  t = "Wildkin-E'ko",
  p = "In Winterspring vecht je tegen machtige wezens die een aangeboren magisch talent lijken te hebben. Deze wildkin kunnen sterke magie gebruiken. Wil je je intelligentie vergroten, breng me dan de E'ko die je bij een van de uilbeesten daar vindt.$B$BDenk eraan: je moet de Cache of Mau'ari in je tassen hebben als je op E'ko wilt jagen.$B$B",
  c = "Mau'ari kan de juju eruit halen voor $N... Gebruik de Cache of Mau'ari om dit over jezelf of je bondgenoten uit te spreken.",
  g = { {"machtige", "mighty (machtig)"}, {"aangeboren", "innate"}, {"talent", "ability, talent"}, {"intelligentie", "intellect"}, {"vergroten", "to increase"}, {"uilbeesten", "owlbeasts (uilbeest)"}, {"Denk eraan", "remember (eraan denken)"}, {"eruit halen", "to draw out, derive"}, {"bondgenoten", "allies (bondgenoot)"}, {"uit te spreken", "to cast, pronounce (uitspreken)"} },
},

[4970] = { en = "Frostsaber Provisions", tier = 4,
  t = "Voedsel voor de frostsabers",
  d = "Als je jezelf wilt bewijzen, kun je beginnen met een heel eenvoudige, maar heel belangrijke taak.$B$BVerzamel vlees van de chimaera's en van de shardtooth-beren in de buurt. Breng het naar mij, zodat ik de frostsabers die getraind worden ermee kan voeren.",
  o = "Verzamel 5 Shardtooth Meats en 5 Chillwind Meats voor Rivern Frostwind in Winterspring.",
  p = "Discipline en vastberadenheid zijn je doelen. Misschien vraag ik je vaak om een eenvoudige taak te doen. Je moet die elke keer zo goed mogelijk uitvoeren.",
  c = "Bedankt voor je hulp, $N. Mijn mening over jou wordt met de tijd beter.",
  g = { {"Voedsel", "food, provisions"}, {"bewijzen", "to prove"}, {"eenvoudige", "simple (eenvoudig)"}, {"taak", "task"}, {"getraind", "trained (trainen)"}, {"voeren", "to feed"}, {"vastberadenheid", "determination"}, {"doelen", "goals (doel)"}, {"uitvoeren", "to perform, carry out"}, {"mening", "opinion"} },
},

[5124] = { en = "Fiery Plate Gauntlets", tier = 4,
  t = "Vurige pantserhandschoenen",
  d = "Bij Thaurissans baard!$B$BWaar heb je die gevonden?$B$BNog belangrijker: wil je er afstand van doen? Natuurlijk zou ik je betalen voor zo'n nobel gebaar.$B$BWeet je wat, $N? Als je mij die ongebakken handschoenen geeft, leer ik je hoe je er zelf een paar maakt. Je hoeft alleen de onderdelen voor me te verzamelen, zodat ik het precieze recept kan vaststellen.$B$BHebben we een deal??$B$BHier is de lijst met wat ik nodig heb. Het niet-betoverde thorium schiet ik zelf voor, omdat jij de handschoenen levert.$b",
  o = "Breng Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire en 4 Star Rubies. Je moet ook je Unfired Plate Gauntlets inleveren.",
  p = "Tijd is geld, $N, en ik heb van allebei niet veel.",
  c = "Zoals beloofd, $N: hier is je recept! Ik doe er ook nog iets extra's bij voor al je harde werk en toewijding. Wat moet ik er tenslotte zelf mee???",
  g = { {"Vurige", "fiery (vurig)"}, {"pantserhandschoenen", "plate gauntlets (pantserhandschoen)"}, {"baard", "beard"}, {"afstand van doen", "to part with"}, {"nobel gebaar", "noble gesture"}, {"ongebakken", "unfired"}, {"onderdelen", "parts, components (onderdeel)"}, {"precieze", "exact (precies)"}, {"vaststellen", "to determine, narrow down"}, {"niet-betoverde", "non-enchanted"}, {"schiet ik voor", "I'll front, advance (voorschieten)"}, {"levert", "supply (leveren)"}, {"inleveren", "to hand in"}, {"toewijding", "dedication"}, {"tenslotte", "after all"} },
},

