[5161] = { en = "Wrath of the Blue Flight", tier = 4,
  t = "De woede van de Blue Flight",
  d = "We begrijpen wat het vervloekte broed van Deathwing probeert te doen, en we weten dat dit niet mag gebeuren.$B$BDoor de bescherming die Blackrock Mountain Nefarian biedt, wordt het voor ons steeds moeilijker om in te grijpen.$B$BWel kunnen we jou kracht geven, sterveling, als je daarvoor kiest.$B$BDe weg die voor je ligt, zit vol gevaren. Je moet beslissen of je onze hulp aanneemt. Denk hierover na en spreek me weer aan als je een besluit hebt genomen.",
  o = "Spreek met Haleh als je verder wilt gaan.",
  c = "Zo zal het zijn...",
  g = { {"woede", "wrath, rage"}, {"vervloekte", "cursed (vervloekt)"}, {"broed", "brood"}, {"bescherming", "protection"}, {"biedt", "affords, offers (bieden)"}, {"in te grijpen", "to intercede, intervene (ingrijpen)"}, {"sterveling", "mortal"}, {"gevaren", "perils, dangers (gevaar)"}, {"aanneemt", "accept (aannemen)"}, {"besluit", "decision"} },
},

[5201] = { en = "Winterfall Intrusion", tier = 4,
  t = "Het binnendringen van de Winterfall",
  d = "De meesten merken mijn aanwezigheid niet op, $N. Maar er is een ergernis die hier in Winterspring stevig geworteld lijkt: de Winterfall-furbolgs.$B$BIk heb de furbolgs nooit direct aangevallen, maar ze lijken gek geworden, bang voor alles op hun pad. Ik heb gezien hoe ze talloze wezens doodden die gewoon de pech hadden om op het verkeerde moment op de verkeerde plek te zijn.$B$BIk ben hun bemoeienis moe. Help me alsjeblieft door terug te vechten. Dood de furbolgs en houd ze weg van Frostsaber Rock.",
  o = "Rivern Frostwind wil dat je 5 Winterfall Shaman en 5 Winterfall Ursa doodt.",
  p = "De furbolgs lijken last te hebben van zo'n achterdocht...",
  c = "Ik ben opgelucht dat we ons even geen zorgen hoeven te maken over het binnendringen van de Winterfall.$B$BJe begint je doorzettingsvermogen te tonen, $N.",
  g = { {"binnendringen", "intrusion"}, {"aanwezigheid", "presence"}, {"ergernis", "annoyance"}, {"geworteld", "rooted (wortelen)"}, {"talloze", "countless (talloos)"}, {"pech", "bad luck, misfortune"}, {"bemoeienis", "meddling"}, {"last hebben van", "suffer from"}, {"achterdocht", "suspicion, paranoia"}, {"opgelucht", "relieved"}, {"doorzettingsvermogen", "perseverance"}, {"tonen", "to show"} },
},

[5981] = { en = "Rampaging Giants", tier = 4,
  t = "Razende reuzen",
  d = "Ongeveer 4.000 jaar geleden redde Tyrande Whisperwind het leven van de frostsaberkoningin, die door razende reuzen werd bedreigd. Sindsdien zijn de frostsabers bondgenoten van de nachtelfen.$B$BDezelfde reuzen die ooit een gevaar waren voor de frostsabers, bestaan nog steeds, niet ver hiervandaan. Ze heten de frostmaul, en ze hebben de grote vallei in het zuiden ingenomen.$B$BBewijs je trouw aan de frostsabers: dood deze reuzen in naam van de frostsaberkoningin, Shy-Rotam!",
  o = "Rivern Frostwind wil dat je 4 Frostmaul Giants en 4 Frostmaul Preservers doodt.",
  p = "Je moet jezelf blijven bewijzen, $N.",
  c = "Uitstekend, $N. Je vastberadenheid is naar behoren genoteerd.",
  g = { {"Razende", "rampaging, raging (razend)"}, {"reuzen", "giants (reus)"}, {"redde", "saved (redden)"}, {"frostsaberkoningin", "frostsaber queen"}, {"bedreigd", "threatened (bedreigen)"}, {"Sindsdien", "since then"}, {"bondgenoten", "allies (bondgenoot)"}, {"ingenomen", "taken over (innemen)"}, {"trouw", "loyalty"}, {"vastberadenheid", "determination"}, {"naar behoren", "duly, properly"}, {"genoteerd", "noted (noteren)"} },
},

[8798] = { en = "A Yeti of Your Own", tier = 4,
  t = "Een eigen yeti",
  c = "Hé! Weet je wat?! Jij bent ook ingenieur! Omdat je me geholpen hebt om mijn vrienden een lesje te leren, ga ik je leren hoe je je eigen mechanische yeti maakt! Dan kan de pret voor altijd doorgaan, en kun je iedereen bang maken die je wilt! Tenminste, als je de onderdelen bij elkaar kunt scharrelen om hem te maken. $B$BWat zeg je ervan, $N? Wil je het geheim leren van het maken van een mechanische yeti?",
  g = { {"ingenieur", "engineer"}, {"een lesje te leren", "to teach a lesson (een lesje leren)"}, {"mechanische", "mechanical (mechanisch)"}, {"pret", "fun"}, {"bang maken", "to scare"}, {"Tenminste", "at least, provided"}, {"onderdelen", "components (onderdeel)"}, {"bij elkaar scharrelen", "to scrape together"}, {"geheim", "secret"} },
},

[9266] = { en = "Making Amends", tier = 4,
  t = "Het goedmaken",
  p = "Je hebt vast iets heel ergs gedaan tegen ons of onze vrienden, $N. Hoe dan ook, ik ben hier om je een manier te bieden om weer bij ons in de gunst te komen.$b$bZoals je weet, is het in Winterspring flink koud. Nu er zoveel van ons goblins uit andere steden komen, kunnen we wel hulp gebruiken om warm te blijven. Breng me wat runecloth en steenkool, dan leg ik een goed woordje voor je in. Maar pas op: onze vijanden zullen het je niet in dank afnemen dat je ons helpt.",
  c = "Bedankt, $N. Je bent goed op weg om het weer goed te maken met onze mooie stad.",
  g = { {"goedmaken", "making amends"}, {"Hoe dan ook", "at any rate"}, {"in de gunst", "in the good graces"}, {"flink", "quite, really"}, {"steenkool", "coal"}, {"een goed woordje voor je in", "put in a good word for you (een goed woordje inleggen)"}, {"pas op", "be warned, watch out (oppassen)"}, {"niet in dank afnemen", "not take kindly to"}, {"goed op weg", "well on the way"} },
},

})

